ROOT=[dict(id='C0171',meaning='山羊；相关的跳跃联想',core='capr-：山羊；确定的交通工具支线经过“跳跃”，任性一支的更早来源则有争议。',image='小山羊轻快跃起，旧式马车也轻轻弹跳。',intro='拉丁 caper、capreolus 经意大利和法语进入跳跃、轻便马车的名称，后来有了 cab。caper 的食物义是另一来源；caprice、capricious 的更早来历存在分歧，留在这里作有边界的旁支对照。',forms='capr- 常在借入中变为 capri-、cabri-；cab 又是 cabriolet 的缩短。相似开头并不保证每种词义都来自山羊。',branches=[['跳跃与交通工具','caper 的跳跃义、cabriolet、cab'],['来源有争议的旁支','caprice、capricious、capriciously'],['同形异源对照','caper 的酸豆义：希腊 kapparis，经拉丁进入英语']],contrasts='不把 caprice 直接断言为山羊派生；不把食物 capers 与跳跃混为一源。cab 的出租车义与驾驶室义则是同一交通工具名称继续扩展。',practice='分别解释菜单里的 capers、电影介绍里的 caper，以及卡车上的 cab。',words=[w for w in family if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/cab','https://www.etymonline.com/word/caper','https://www.etymonline.com/word/caprice'])]
